import re

def node_by_title(doc, title):
    for node in doc['nodes']:
        if node['title'] == title:
            return node
    return None

def children(doc, node):
    return [node_by_id(doc, cid) for cid in node.get('children', [])]

def node_by_id(doc, node_id):
    for node in doc['nodes']:
        if node['node_id'] == node_id:
            return node
    return None

def table_rows(node):
    if node['kind'] != 'table':
        return []
    cols = node['table']['columns']
    rows = node['table']['rows']
    return [(i, {cols[j]: row[j] for j in range(len(cols))}) for i, row in enumerate(rows)]

def entities(doc, scope):
    node = node_by_title(doc, f"{scope}: Objects")
    if not node:
        return []
    ents = []
    for line in node.get('lines', []):
        # Format: "Object 0: purple metal sphere (color=purple, material=metal, shape=sphere)"
        match = re.match(r"^(Object \d+): (.*?) \(", line)
        if match:
            ents.append({"id": match.group(1), "description": match.group(2)})
    return ents

def recorded_end(doc, scope):
    node = node_by_title(doc, f"{scope}: Motion log")
    if not node or node['kind'] != 'table':
        return None
    rows = table_rows(node)
    frames = []
    for _, row in rows:
        try:
            frames.append(float(row['frame']))
        except (ValueError, KeyError):
            pass
    return max(frames) if frames else None

def inputs(doc, scope):
    event_node = node_by_title(doc, f"{scope}: Events")
    motion_node = node_by_title(doc, f"{scope}: Motion log")
    if not event_node or not motion_node:
        return []

    motion_rows = table_rows(motion_node)
    entity_map = {e['id']: e['description'] for e in entities(doc, scope)}

    inputs_list = []
    for i, line in enumerate(event_node.get('lines', [])):
        # "Frame 0: Object 1 (brown rubber cube) is in view when the video begins."
        # "Frame 13: Object 0 (purple metal sphere) enters the scene."
        match = re.match(r"Frame (\d+): (Object \d+) \(.*?\) (is in view when the video begins|enters the scene)", line)
        if match:
            frame = float(match.group(1))
            ent_id = match.group(2)

            # Find the state in motion log for this object at this frame
            desc = entity_map.get(ent_id, "")
            # Motion log object column format: "1 brown rubber cube"
            # The ID is "Object 1", so we look for "1 " + description
            id_num = ent_id.split(' ')[1]
            obj_search_str = f"{id_num} {desc}"

            state_fields = {}
            state_src = []
            for row_idx, row in motion_rows:
                if float(row['frame']) == frame and row['object'] == obj_search_str:
                    state_fields = {
                        "x": float(row['x']),
                        "y": float(row['y']),
                        "vx": float(row['vx']),
                        "vy": float(row['vy']),
                        "speed": float(row['speed'])
                    }
                    state_src = [motion_node['node_id'], row_idx]
                    break

            inputs_list.append({
                "id": f"input_{i}",
                "time": frame,
                "kind": "arrival" if "enters" in line else "initial_state",
                "entities": [ent_id],
                "fields": state_fields,
                "src": [[event_node['node_id'], i]] + state_src if state_src else [[event_node['node_id'], i]]
            })

    return inputs_list

def outcomes(doc, scope):
    event_node = node_by_title(doc, f"{scope}: Events")
    if not event_node:
        return []

    outcomes_list = []
    for i, line in enumerate(event_node.get('lines', [])):
        # "Frame 20: Object 0 (purple metal sphere) collides with Object 1 (brown rubber cube)."
        # "Frame 50: Object 2 (yellow metal sphere) exits the scene."
        match_collision = re.match(r"Frame (\d+): (Object \d+) \(.*?\) collides with (Object \d+) \(.*?\)", line)
        match_exit = re.match(r"Frame (\d+): (Object \d+) \(.*?\) exits the scene", line)

        if match_collision:
            outcomes_list.append({
                "time": float(match_collision.group(1)),
                "kind": "collision",
                "entities": [match_collision.group(2), match_collision.group(3)],
                "value": None,
                "src": [[event_node['node_id'], i]]
            })
        elif match_exit:
            outcomes_list.append({
                "time": float(match_exit.group(1)),
                "kind": "exit",
                "entities": [match_exit.group(2)],
                "value": None,
                "src": [[event_node['node_id'], i]]
            })

    return outcomes_list

