def inputs(doc, scope):
    obj_node = node_by_title(doc, f"{scope}: Objects")
    ev_node = node_by_title(doc, f"{scope}: Events")
    mo_node = node_by_title(doc, f"{scope}: Motion log")
    if not (obj_node and ev_node and mo_node):
        return []

    # Map Object ID to its properties and the line index in the Objects list
    obj_data = {}
    for i, line in enumerate(obj_node.get('lines', [])):
        # Format: "Object 0: purple metal sphere (color=purple, material=metal, shape=sphere)"
        match = re.match(r"^(Object \d+): (.*?) \(color=(.*?), material=(.*?), shape=(.*?)\)", line)
        if match:
            oid = match.group(1)
            obj_data[oid] = {
                "desc": match.group(2),
                "props": {"color": match.group(3), "material": match.group(4), "shape": match.group(5)},
                "line_idx": i
            }

    mo_rows = table_rows(mo_node)
    inputs_list = []
    for i, line in enumerate(ev_node.get('lines', [])):
        # Initial state or arrival events
        match = re.match(r"Frame (\d+): (Object \d+) \(.*?\) (is in view when the video begins|enters the scene)", line)
        if match:
            frame = float(match.group(1))
            oid = match.group(2)
            kind = "initial_state" if "begins" in match.group(3) else "arrival"

            # Search Motion log for the state of the object at this specific frame
            state_fields = {}
            state_loc = None
            desc = obj_data.get(oid, {}).get("desc", "")
            # Motion log identifies objects as "1 brown rubber cube"
            obj_search_str = f"{oid.split(' ')[1]} {desc}"

            for row_idx, row in mo_rows:
                try:
                    if float(row['frame']) == frame and row['object'] == obj_search_str:
                        state_fields = {
                            "x": float(row['x']),
                            "y": float(row['y']),
                            "vx": float(row['vx']),
                            "vy": float(row['vy']),
                            "speed": float(row['speed'])
                        }
                        state_loc = [mo_node['node_id'], row_idx, ['frame', 'object', 'x', 'y', 'vx', 'vy', 'speed']]
                        break
                except (ValueError, KeyError):
                    continue

            # Gather constant properties from the Objects list
            props = obj_data.get(oid, {}).get("props", {})
            fields = {**props, **state_fields}

            # Collect all sources used to determine this input
            src = [[ev_node['node_id'], i]]
            if state_loc:
                src.append(state_loc)
            if oid in obj_data:
                src.append([obj_node['node_id'], obj_data[oid]['line_idx']])

            inputs_list.append({
                "id": f"input_{i}",
                "time": frame,
                "kind": kind,
                "entities": [oid],
                "fields": fields,
                "src": src
            })

    return inputs_list

