    ev_node = node_by_title(doc, f"{scope}: Events")
    if not ev_node:
        return []

    outcomes_list = []
    for i, line in enumerate(ev_node.get('lines', [])):
        # Collision events: "Frame 20: Object 0 (purple metal sphere) collides with Object 1 (brown rubber cube)."
        coll_match = re.match(r"Frame (\d+): (Object \d+) \(.*?\) collides with (Object \d+) \(.*?\)", line)
        # Exit events: "Frame 50: Object 2 (yellow metal sphere) exits the scene."
        exit_match = re.match(r"Frame (\d+): (Object \d+) \(.*?\) exits the scene", line)

        if coll_match:
            outcomes_list.append({
                "time": float(coll_match.group(1)),
                "kind": "collision",
                "entities": [coll_match.group(2), coll_match.group(3)],
                "value": None,
                "src": [[ev_node['node_id'], i]]
            })
        elif exit_match:
            outcomes_list.append({
                "time": float(exit_match.group(1)),
                "kind": "exit",
                "entities": [exit_match.group(2)],
